    fromTemporaryCredentials: jest.fn(() => ({})),
}));

const { Ec2InstanceDataGathererService } = await import('./ec2InstanceDataGatherer.service.js');

const DIMENSION = 'dim-uptime';
const INC = 0.08333333;

function inst(id: string, customerTag?: string) {
    const Tags = [{ Key: 'meteringDimensionId', Value: DIMENSION }];
    if (customerTag !== undefined) {
        Tags.push({ Key: 'meteringCustomerId', Value: customerTag });
    }
    return { InstanceId: id, InstanceType: 'm5.large', Tags };
}

describe('Ec2InstanceDataGathererService.gatherUsage', () => {
    beforeEach(() => {
        jest.clearAllMocks();
        mockListDocumentKeys.mockResolvedValue([
            'onboarding/customers/harbor.json',
            'onboarding/customers/lattice.json',
        ]);
    });

    function stubRegistry(registry: any, customers: Record<string, any>) {
        mockGetDocument.mockImplementation(async (_bucket: string, key: string) => {
            if (key === 'reg.json') return registry;
            if (key.includes('harbor')) return customers.harbor;
            if (key.includes('lattice')) return customers.lattice;
            throw new Error('unexpected key ' + key);
        });
    }

    const registry = {
        businessID: 'biz',
        customerRecordPrefix: 'onboarding/customers/',
        accounts: [
            { accountId: '11', roleArn: 'arn:11', region: 'us-east-1' },
            { accountId: '22', roleArn: 'arn:22', region: 'us-east-1' },
        ],
    };
    const customers = {
        harbor: { customerId: 'cus_harbor', accounts: [{ accountId: '11', dedicated: true }, { accountId: '22' }] },
        lattice: { customerId: 'cus_lattice', accounts: [{ accountId: '22' }] },
    };

    async function run() {
        const svc = new Ec2InstanceDataGathererService();
        return svc.gatherUsage({ businessID: 'biz', dimensionId: DIMENSION, registryBucket: 'b', registryKey: 'reg.json' });
    }

    it('bills all machines in a dedicated account to its customer regardless of tags', async () => {
        stubRegistry(registry, customers);
        mockGetInstanceWithFilters.mockImplementation(async (region: string, creds: any, filters: any) => {
            // distinguish account by call order
            return [];
        });
        // account 11 has three machines: tagged harbor, untagged, tagged the OTHER customer
        mockGetInstanceWithFilters
            .mockResolvedValueOnce([inst('i-1', 'cus_harbor'), inst('i-2'), inst('i-3', 'cus_lattice')])
            .mockResolvedValueOnce([]); // account 22 empty

        const res = await run();
        expect(res).toHaveLength(1);
        expect(res[0].customerId).toBe('cus_harbor');
        expect(res[0].recordValue).toBeCloseTo(INC * 3, 8);
        expect(res[0].metadata.instanceCount).toBe(3);
    });

    it('splits shared-account machines evenly among onboarded named tenants', async () => {
        stubRegistry(registry, customers);
        mockGetInstanceWithFilters
            .mockResolvedValueOnce([]) // account 11 empty
            .mockResolvedValueOnce([
                inst('i-11', 'cus_harbor,cus_lattice'), // split evenly
                inst('i-12'), // unplaceable
                inst('i-13', 'cus_lattice'), // full to lattice
            ]);

        const res = await run();
        const map: Record<string, any> = Object.fromEntries(res.map((r) => [r.customerId, r]));
        expect(map['cus_harbor'].recordValue).toBeCloseTo(INC / 2, 8);
        expect(map['cus_lattice'].recordValue).toBeCloseTo(INC / 2 + INC, 8);
        expect(map['cus_harbor'].metadata.instanceCount).toBe(1);
        expect(map['cus_lattice'].metadata.instanceCount).toBe(2);
        // i-12 unplaceable => never appears, no bogus comma customer id
        expect(res.find((r) => r.customerId.includes(','))).toBeUndefined();
    });

    it('drops shared-account usage naming no onboarded tenant', async () => {
        stubRegistry(registry, customers);
        mockGetInstanceWithFilters
            .mockResolvedValueOnce([]) // account 11
            .mockResolvedValueOnce([inst('i-x', 'cus_unknown'), inst('i-y', '')]);
        const res = await run();
        expect(res).toHaveLength(0);
    });

    it('treats conflicting dedicated claims as a shared account', async () => {
        const conflict = {
            harbor: { customerId: 'cus_harbor', accounts: [{ accountId: '11', dedicated: true }] },
            lattice: { customerId: 'cus_lattice', accounts: [{ accountId: '11', dedicated: true }] },
        };
        stubRegistry({ ...registry, accounts: [{ accountId: '11', roleArn: 'arn', region: 'us-east-1' }] }, conflict);
        mockGetInstanceWithFilters.mockResolvedValueOnce([inst('i-1', 'cus_harbor'), inst('i-2')]);
        const res = await run();
        const map: Record<string, any> = Object.fromEntries(res.map((r) => [r.customerId, r]));
        // shared: i-1 -> harbor (named+onboarded), i-2 -> untagged unplaceable
        expect(map['cus_harbor'].recordValue).toBeCloseTo(INC, 8);
        expect(map['cus_lattice']).toBeUndefined();
    });
});
